<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {ArrowLeft,Check,Download,Upload,Search} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import Sheet from '../components/Sheet.vue'
import {readerThemeStyle,validateReaderTheme,type ReaderTheme} from './themes'
import {themePresets,presetTheme,appearanceSelection,resolvedAppearance,parseThemeJSON,exportThemeJSON,importReaderTheme,saveAppearance,themeFileLimit,type AppearanceSelection} from './appearance'
const store=useLocal(),preference=ref<Document<Record<string,unknown>>|null>(null),custom=ref<Document<ReaderTheme>[]>([])
const selection=ref<AppearanceSelection>(appearanceSelection()),mode=ref<'light'|'dark'>('light'),search=ref(''),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(true),importOpen=ref(false),raw=ref(''),parsed=ref<ReaderTheme|null>(null),fileInput=ref<HTMLInputElement|null>(null)
let disposed=false,pendingOperation:string|null=null,fileGeneration=0
const current=(vault:typeof store.vault)=>!disposed&&store.vault===vault&&!!vault?.unlocked
const presets=computed(()=>themePresets.filter(p=>p.mode===mode.value&&p.value.name.includes(search.value.trim())))
const selectedCustom=computed(()=>custom.value.find(row=>row.id===selection.value.customThemeId)||null)
const preview=computed(()=>selection.value.builtinThemeId?presetTheme(selection.value.builtinThemeId)?.value||null:selectedCustom.value?.value||null)
const displayTheme=computed(()=>preview.value||themePresets.find(p=>p.id===(selection.value.theme==='dark'?'builtin:warm-night':'builtin:warm'))!.value)
async function load(){const vault=store.vault;if(!vault)return;loading.value=true;try{const result=await resolvedAppearance(vault),rows=(await vault.list<ReaderTheme>('settings')).filter(row=>row.value.assetType==='reader-theme'),valid=rows.filter(row=>{try{validateReaderTheme(row.value,row.id);return true}catch{return false}});if(!current(vault))return;preference.value=result.preference;selection.value=result.selection;mode.value=result.mode;custom.value=valid;error.value=result.warning||(valid.length!==rows.length?'部分旧主题无法使用，原记录仍保留':'');pendingOperation=null}catch(e){if(current(vault))error.value=(e as Error).message}finally{if(current(vault))loading.value=false}}
function choose(id:string,kind:'builtin'|'custom'){pendingOperation=null;notice.value='';error.value='';selection.value={...selection.value,builtinThemeId:kind==='builtin'?id:null,customThemeId:kind==='custom'?id:null}}
function base(){pendingOperation=null;selection.value={...selection.value,builtinThemeId:null,customThemeId:null,theme:mode.value};notice.value='';error.value=''}
async function save(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';notice.value='';pendingOperation??='appearance:'+crypto.randomUUID();try{await saveAppearance(vault,preference.value,selection.value,selectedCustom.value,pendingOperation);if(!current(vault))return;await load();if(current(vault))notice.value='外观已保存'}catch(e){if(current(vault))error.value=(e as Error).message}finally{if(current(vault))busy.value=false}}
function download(){try{const value=displayTheme.value,url=URL.createObjectURL(new Blob([exportThemeJSON(value)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=value.name.replace(/[\\/:*?"<>|]/g,'-')+'.theme.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
function invalidatePreview(){fileGeneration++;parsed.value=null}
function openImport(){invalidatePreview();raw.value='';error.value='';importOpen.value=true}
function closeImport(){if(busy.value)return;invalidatePreview();importOpen.value=false;raw.value=''}
function inspect(){invalidatePreview();error.value='';try{parsed.value=parseThemeJSON(raw.value)}catch(e){error.value=(e as Error).message}}
async function readFile(event:Event){const vault=store.vault,file=(event.target as HTMLInputElement).files?.[0];(event.target as HTMLInputElement).value='';invalidatePreview();const generation=fileGeneration;raw.value='';error.value='';if(!file||!vault)return;try{if(file.size>themeFileLimit)throw Error('主题文件超过 64 KiB');const bytes=await file.arrayBuffer();if(!current(vault)||!importOpen.value||generation!==fileGeneration)return;const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);raw.value=text;inspect()}catch(e){if(current(vault)&&importOpen.value&&generation===fileGeneration)error.value=(e as Error).message}}
async function importTheme(){const vault=store.vault;if(!vault||busy.value||!parsed.value)return;const input=raw.value;busy.value=true;error.value='';notice.value='';try{const row=await importReaderTheme(vault,input);if(!current(vault))return;custom.value=[...custom.value.filter(r=>r.id!==row.id),row];importOpen.value=false;raw.value='';parsed.value=null;if(row.value.enabled){choose(row.id,'custom');notice.value='主题已导入'}else notice.value='主题已导入，当前处于停用状态'}catch(e){if(current(vault))error.value=(e as Error).message}finally{if(current(vault))busy.value=false}}
onMounted(()=>void load())
onUnmounted(()=>{disposed=true;invalidatePreview();raw.value='';parsed.value=null;preference.value=null;custom.value=[]})
</script>
<template>
 <section class="appearance-page">
  <header class="final-page-heading"><div class="final-heading-copy"><RouterLink class="final-text-link" to="/local/settings"><ArrowLeft :size="17"/>我的</RouterLink><h1>外观与阅读</h1></div><button class="final-icon-button" aria-label="导入主题 JSON" :disabled="busy" @click="openImport"><Upload :size="19"/></button></header>
  <p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="notice" role="status" class="appearance-notice">{{notice}}</p><p v-if="loading" role="status">正在读取外观…</p>
  <template v-else>
   <div class="appearance-preview" :style="readerThemeStyle(displayTheme)"><span>{{displayTheme.name}}</span><p :style="{fontSize:selection.fontSize+'px'}">雾里的灯，终于有了回音。</p><small>酒馆 · 每一页都有新的可能</small><i aria-hidden="true"/></div>
   <fieldset :disabled="busy" class="appearance-form">
    <div class="appearance-toolbar"><div class="appearance-modes" role="group" aria-label="配色类别"><button type="button" :aria-pressed="mode==='light'" @click="mode='light'">日间</button><button type="button" :aria-pressed="mode==='dark'" @click="mode='dark'">夜间</button></div><label class="appearance-search"><Search :size="17"/><input v-model="search" aria-label="搜索配色" placeholder="寻找一种颜色" maxlength="100"></label></div>
    <div class="appearance-palettes" aria-label="内置配色"><button v-for="p in presets" :key="p.id" type="button" class="appearance-palette" :aria-pressed="selection.builtinThemeId===p.id" :style="{background:p.value.colors.paper,color:p.value.colors.ink,borderColor:selection.builtinThemeId===p.id?p.value.colors.accent:undefined}" @click="choose(p.id,'builtin')"><span class="palette-dot" :style="{background:p.value.colors.accent}"/><strong>{{p.value.name}}</strong><Check v-if="selection.builtinThemeId===p.id" :size="18"/></button></div>
    <p v-if="!presets.length" class="final-subtle">没有匹配的配色</p>
    <section v-if="custom.length" class="appearance-custom"><h2>我的主题</h2><div class="appearance-palettes"><button v-for="row in custom" :key="row.id" class="appearance-palette" type="button" :disabled="!row.value.enabled" :aria-pressed="selection.customThemeId===row.id" @click="choose(row.id,'custom')"><span class="palette-dot" :style="{background:row.value.colors.accent}"/><strong>{{row.value.name}}</strong><Check v-if="selection.customThemeId===row.id" :size="18"/><small>{{row.value.enabled?'已导入':'已停用'}}</small></button></div></section>
    <div class="appearance-preferences"><label>字号 · {{selection.fontSize}}<input v-model.number="selection.fontSize" aria-label="阅读字号" type="range" min="14" max="36" @input="pendingOperation=null"></label><label>界面动效<select v-model="selection.motion" aria-label="界面动效" @change="pendingOperation=null"><option value="system">跟随系统</option><option value="reduced">减少动效</option></select></label></div>
    <div class="appearance-actions"><button type="button" class="final-primary" @click="save">{{busy?'正在保存…':'保存外观'}}</button><button type="button" @click="base">基础配色</button><button type="button" @click="download"><Download :size="17"/>导出主题</button></div>
   </fieldset>
  </template>
  <Sheet v-if="importOpen" title="导入主题" @close="closeImport">
   <div class="appearance-import"><input ref="fileInput" type="file" accept=".json,application/json" hidden :disabled="busy" @change="readFile"><button :disabled="busy" @click="fileInput?.click()">选择 JSON 文件</button><label>主题 JSON<textarea v-model="raw" aria-label="主题 JSON" rows="10" maxlength="65537" :disabled="busy" @input="invalidatePreview"/></label><button :disabled="busy||!raw" @click="inspect">预览主题</button><p v-if="error" role="alert" class="final-error">{{error}}</p><div v-if="parsed" class="appearance-preview" :style="readerThemeStyle(parsed)"><span>{{parsed.name}}</span><p>雾里的灯，终于有了回音。</p><small>{{parsed.enabled?'可用主题':'已停用主题'}}</small></div><button class="final-primary" :disabled="busy||!parsed" @click="importTheme">{{busy?'正在导入…':'导入主题'}}</button></div>
  </Sheet>
 </section>
</template>
<style scoped>
.appearance-page{max-width:1120px}.appearance-form{border:0;padding:0;margin:0;min-width:0}.appearance-preview{position:relative;margin:24px 0;padding:30px 32px;border-radius:16px;border:1px solid var(--edge);background:var(--paper);color:var(--ink);overflow:hidden}.appearance-preview>span{display:block;overflow-wrap:anywhere;color:var(--quiet);font-size:13px;letter-spacing:.1em}.appearance-preview>p{position:relative;font-family:var(--font-serif);line-height:1.8;margin:18px 0;overflow-wrap:anywhere}.appearance-preview>small{color:var(--quiet)}.appearance-preview>i{position:absolute;width:100px;height:100px;border:1px solid var(--accent);border-radius:50%;right:-35px;top:-35px;opacity:.35}.appearance-toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:28px 0 18px}.appearance-modes{display:flex;gap:8px}.appearance-modes button[aria-pressed=true]{color:var(--accent);background:var(--wash);border-color:var(--accent)}.appearance-search{position:relative;max-width:320px;width:100%}.appearance-search svg{position:absolute;left:14px;top:16px}.appearance-search input{padding-left:42px}.appearance-palettes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.appearance-palettes .appearance-palette{position:relative;display:grid;grid-template-columns:24px minmax(0,1fr) 20px;gap:9px 10px;min-height:92px;padding:18px;text-align:left;border-radius:14px;transition:box-shadow .18s}.appearance-palette[aria-pressed=true]{box-shadow:inset 0 0 0 1px var(--accent)}.appearance-palette strong{min-width:0;font-weight:550;overflow-wrap:anywhere}.appearance-palette small{grid-column:2/4;font-size:12px;opacity:.8}.palette-dot{width:18px;height:18px;border-radius:50%;align-self:center}.appearance-preferences{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:32px 0}.appearance-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0}.appearance-actions button{display:inline-flex;align-items:center;gap:8px}.appearance-custom{margin-top:28px}.appearance-custom h2{margin-bottom:16px}.appearance-import{display:grid;gap:18px}.appearance-import label{display:grid;gap:8px}.appearance-import textarea{min-height:180px;width:100%;padding:14px;font:13px/1.7 ui-monospace,monospace;border:1px solid var(--edge);border-radius:12px;background:var(--canvas);color:var(--ink)}.appearance-import button{min-height:44px}.appearance-import .appearance-preview{margin:0}.appearance-notice{color:var(--good)}
@media(max-width:600px){.appearance-preview{padding:24px}.appearance-toolbar{align-items:stretch;flex-direction:column;gap:14px}.appearance-search{max-width:none}.appearance-palettes{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.appearance-palettes .appearance-palette{padding:16px 12px;gap:8px}.appearance-preferences{grid-template-columns:1fr;gap:20px}.appearance-actions{gap:8px}.appearance-actions .final-primary{flex:1}.appearance-modes button{flex:1}.appearance-modes{width:100%}}
</style>
